import{_ as t,o as n,c as i,a2 as o}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/en/check-problem-list.png",p=JSON.parse('{"title":"Design check and suggestions","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/check.md","filePath":"en/features/check.md"}'),r={name:"en/features/check.md"};function d(s,e,l,h,c,g){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="design-check-and-suggestions" tabindex="-1">Design check and suggestions <a class="header-anchor" href="#design-check-and-suggestions" aria-label="Permalink to &quot;Design check and suggestions&quot;">​</a></h1><p>The design check that runs while you draw, fixing and ignoring findings in the problem list, suggestions while typing, and relationship name matching.</p><p>There is a short introduction in <a href="/relio/en/quick/draw#good-to-know">Draw tables, columns and relationships</a> in Quick start.</p><h2 id="design-check" tabindex="-1">Design check <a class="header-anchor" href="#design-check" aria-label="Permalink to &quot;Design check&quot;">​</a></h2><p>The model is checked after every edit and problems are reported. No finding ever blocks saving or exporting.</p><table tabindex="0"><thead><tr><th>Severity</th><th>Meaning</th><th>On the canvas</th></tr></thead><tbody><tr><td>Error ●</td><td>A problem that makes the DDL fail when run</td><td>Mark on the table header (and on the Outline item), wavy underline on the column line</td></tr><tr><td>Warning ▲</td><td>A problem worth fixing</td><td>Mark on the table header (and on the Outline item), wavy underline on the column line</td></tr><tr><td>Info i</td><td>Good to know</td><td>Only in the problem list by default</td></tr></tbody></table><ul><li>Hover over a mark to read the finding.</li><li>Table and view items in the Outline get the same marks (the most severe finding for the table and its columns). <a href="/relio/en/features/canvas#outline">Canvas and palette › Outline</a></li><li>View › <strong>Show design check marks</strong> turns all canvas marks on or off. Turn on View › <strong>Show info marks on canvas</strong> to draw info findings on the canvas too.</li><li>The <strong>Problems: …</strong> button at the right end of the category tab row counts only errors and warnings (not info or ignored findings) and hides when there is nothing to count. Click it to open the problem list.</li><li>Checks follow the document&#39;s target database and version (for example reserved words and name length limits). Change the target version at the left end of the status bar.</li><li><kbd>F8</kbd> / <kbd>Shift</kbd>+<kbd>F8</kbd> go to the next and previous finding.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Rule ID</th><th>Default severity</th><th>What it checks</th><th>Fix button</th></tr></thead><tbody><tr><td>No primary key</td><td><code>pk-missing</code></td><td>Warning</td><td>The table has no primary key (PK) column</td><td>Opens the properties dialog</td></tr><tr><td>Foreign key without index</td><td><code>fk-no-index</code></td><td>Info</td><td>No index, primary key or unique key starts with the foreign key (FK) columns (not checked for MySQL and MariaDB)</td><td>Create index</td></tr><tr><td>Type differs from reference candidate</td><td><code>fk-candidate-type</code></td><td>Warning</td><td>A column without a relationship matches another table&#39;s primary key by name but has a different type</td><td>Match type</td></tr><tr><td>Reserved word name</td><td><code>reserved-word</code></td><td>Error</td><td>The physical name is a reserved word in the target database and version (tables, views, columns, indexes, sequences, triggers). Info when it only might fail in that version</td><td></td></tr><tr><td>Empty physical name</td><td><code>physical-name-empty</code></td><td>Error</td><td>A table, view or column has an empty physical name</td><td>Use the word&#39;s physical name</td></tr><tr><td>Empty type</td><td><code>type-empty</code></td><td>Error</td><td>A column has an empty type</td><td></td></tr><tr><td>Duplicate table name</td><td><code>duplicate-table-name</code></td><td>Error</td><td>Tables, views or sequences in the same schema share a physical name</td><td></td></tr><tr><td>Invalid characters in physical name</td><td><code>physical-name-chars</code></td><td>Error</td><td>Spaces or symbols in a physical name, or a leading digit (non-ASCII letters such as Hangul: warning)</td><td></td></tr><tr><td>Name too long</td><td><code>identifier-too-long</code></td><td>Error</td><td>Exceeds the identifier length limit of the target database and version (warning for PostgreSQL)</td><td></td></tr><tr><td>Table without columns</td><td><code>no-columns</code></td><td>Error</td><td>The table has no columns</td><td></td></tr><tr><td>Duplicate column name</td><td><code>duplicate-column-name</code></td><td>Error</td><td>Columns in one table share a physical name</td><td></td></tr><tr><td>Duplicate logical name</td><td><code>duplicate-logical-name</code></td><td>Warning</td><td>Tables or views in the document share a logical name</td><td></td></tr><tr><td>View without SQL</td><td><code>view-no-sql</code></td><td>Error</td><td>The view has no SQL</td><td></td></tr><tr><td>Unsupported full-text index</td><td><code>fulltext-unsupported</code></td><td>Warning</td><td>Full-text indexes are available only for MySQL and MariaDB</td><td></td></tr><tr><td>Tablespace without properties</td><td><code>tablespace-no-properties</code></td><td>Warning</td><td>A tablespace is used but has no properties for the current environment</td><td></td></tr></tbody></table><p>Rule IDs are used with <code>--disable</code> and <code>--only</code> of the command-line <code>relio lint</code>. The default severity is the value before you change it in Settings; as noted in parentheses, some rules report at a different level in certain cases.</p><p>&quot;Use the word&#39;s physical name&quot; appears only when exactly one word in the dictionary has the same logical name as the item with the empty physical name (it does not appear for foreign key columns), and fills in that word&#39;s physical name. For findings without a fix button, double-click the item and fix it in the properties dialog. Turn each rule on or off and change its severity in <a href="/relio/en/features/preferences#design-check">Settings › Design check</a>.</p><h2 id="problem-list" tabindex="-1">Problem list <a class="header-anchor" href="#problem-list" aria-label="Permalink to &quot;Problem list&quot;">​</a></h2><p>The problem list in the bottom panel (<kbd>Ctrl</kbd>+<kbd>J</kbd>, or View › Panels › Bottom panel (Problem list)) collects design check findings, repairs made when opening a file, and DDL export warnings.</p><ul><li>Toggle each severity, filter with the <strong>Find target or message</strong> field, and use <strong>Group by rule</strong> to see findings per rule.</li><li>Click an item to go to that object on the canvas and highlight it briefly; double-click to open its properties dialog. If the object is not in the current category tab, Relio tells you to look for it in the &quot;All&quot; tab.</li><li>Use the fix button on an item (for example <strong>Create index</strong> or <strong>Match type</strong>) or <strong>Fix all: …</strong> on a rule header to fix them in one go. One undo reverts it.</li><li>Info findings are folded into one line per rule; click it to expand.</li><li>Select several rows with <kbd>Ctrl</kbd> or <kbd>Shift</kbd> and right-click for <strong>Fix all selected</strong>, <strong>Ignore here</strong>, <strong>Turn off &#39;…&#39; for this file</strong>, <strong>Copy list (Markdown)</strong> and <strong>Copy as CSV</strong>.</li><li>Right-click a node, column or line on the canvas to fix or ignore findings from <strong>Findings (n) ▸</strong> at the bottom of the menu.</li></ul><figure class="shot" data-scene="check-problem-list"><img src="'+a+'" alt="Problem list — grouped by rule, with an info finding expanded to show its fix button" loading="lazy"><figcaption>Problem list — grouped by rule, with an info finding expanded to show its fix button</figcaption></figure><h2 id="ignoring-findings" tabindex="-1">Ignoring findings <a class="header-anchor" href="#ignoring-findings" aria-label="Permalink to &quot;Ignoring findings&quot;">​</a></h2><ul><li><strong>Ignore here</strong> — Hides that one finding.</li><li><strong>Turn off &#39;…&#39; for this file</strong> — Turns that rule off for this file.</li><li>Ignores are recorded per file in the app settings on this PC, not in the <code>.erm</code>. The document is not marked as changed, and ignores are not shared with your team.</li><li>Use <strong>Show ignored</strong> in the problem list to see them and <strong>Stop ignoring</strong> to bring one back. <strong>Remove ignores whose target no longer exists</strong> cleans up stale ones.</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>The command-line <code>relio lint</code> does not use this PC&#39;s ignores, so it gives the same result on every PC. Turn rules off in CI with <code>--disable</code>. <a href="/relio/en/features/cli#relio-lint">Command line › relio lint</a></p></div><h2 id="notes-where-you-type" tabindex="-1">Notes where you type <a class="header-anchor" href="#notes-where-you-type" aria-label="Permalink to &quot;Notes where you type&quot;">​</a></h2><ul><li>The table and column properties dialogs show a line under the field for an empty physical name, a table with the same name, Korean letters, spaces, reserved words and an empty type (nothing is blocked).</li><li>In a new column dialog, notes for fields you have not touched wait until you type in that field or leave it once.</li><li>The DDL export dialog shows &quot;This document has n errors that make the DDL fail&quot;. <a href="/relio/en/features/ddl">DDL</a></li></ul><h2 id="suggestions-while-typing" tabindex="-1">Suggestions while typing <a class="header-anchor" href="#suggestions-while-typing" aria-label="Permalink to &quot;Suggestions while typing&quot;">​</a></h2><p>When you type a physical or logical name in the column properties dialog, candidates come from the word dictionary and the columns of other tables.</p><ul><li>The list opens <strong>above</strong> the field so it does not cover the fields below. It shows up to 8 candidates.</li><li>Pick with <kbd>↓</kbd> / <kbd>↑</kbd> and accept with <kbd>Enter</kbd> or <kbd>Tab</kbd> to fill in the name, type, length and logical name at once. Clicking a row also accepts it.</li><li>An <kbd>Enter</kbd> pressed without first picking with <kbd>↓</kbd> does not accept a candidate. Hovering over a row does not pick it either.</li><li>If you accepted the wrong one, click <strong>Undo fill</strong>.</li></ul><h2 id="relationship-name-matching" tabindex="-1">Relationship name matching <a class="header-anchor" href="#relationship-name-matching" aria-label="Permalink to &quot;Relationship name matching&quot;">​</a></h2><ul><li>With the 1:N relationship tool, clicking the parent table highlights candidate child tables that have columns with matching names (&quot;n candidates with matching names are highlighted&quot;).</li><li>If a new relationship leaves the child with two columns of the same name, a notice bar appears. <strong>Use the existing column as the foreign key</strong> switches the original column into the foreign key in one step (its type follows the parent). <strong>Leave as is</strong> closes the bar.</li></ul><p>Suggestions while typing, relationship name matching and canvas marks can be turned off in <a href="/relio/en/features/preferences#design-check">Settings › Design check</a>.</p>',26)])])}const m=t(r,[["render",d]]);export{p as __pageData,m as default};
